#!/usr/bin/env python3
"""Generate unsent, consent-required email drafts and a local preview gallery."""
from pathlib import Path
import html
ROOT = Path(__file__).resolve().parents[1]
OUT = ROOT / 'docs/email-drafts'
OUT.mkdir(parents=True, exist_ok=True)
letters = [
 ('01-welcome','Day 0 · after optional email consent','A quieter place to read','One useful idea to begin with.','Your next page\ncan wait for you.',"Welcome to Hadithly. Start with any collection, read in your language, and take as much time as you need.","A bookmark is enough","Hold a hadith to save it. You can return from Saved whenever you choose. Your saved items stay private.",'Open Hadithly','https://hadithly.app/','A few quiet minutes can be enough.','This is the first of three reading tips you chose to receive.'),
 ('02-offline','Day 4 · from optional email consent','Take a collection with you','A small setup for the moments without a connection.','A little preparation.\nMore room to read.',"On a journey, between appointments, or somewhere with a weak connection, a downloaded collection keeps the text close.","Set it up while online","Open Settings, then Offline storage. Choose a collection and download it. Only completed, verified downloads become available offline.",'Open Hadithly','https://hadithly.app/','Downloaded original text can work without signing in.','This is the second of three reading tips you chose to receive.'),
 ('03-help','Day 12 · from optional email consent','Make your reading space your own','Larger text, a softer page, or help when something feels wrong.','Make the page\ncomfortable for you.',"A good reading space starts with a page you can read comfortably. Hadithly lets you change the type size and appearance without changing what you have saved.","A small adjustment","Open the reader menu, then Settings. Try a larger text size or the Paper appearance. If a screen is difficult to use, tell us what needs to change.",'Ask for help','https://hadithly.app/support/','No passwords, private notes, or reading history are needed.','This is the last reading tip in this short series.')
]
cards=[]
for slug,timing,subject,preheader,title,intro,tip,body,cta,url,closing,reason in letters:
 e=html.escape
 title=e(title).replace('\n','<br>')
 letter=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="color-scheme" content="light"><title>{e(subject)} · Hadithly draft</title></head>
<body style="margin:0;background:#eeece5;color:#213e34;font-family:Georgia,'Times New Roman',serif;">
<div style="display:none;max-height:0;overflow:hidden;mso-hide:all;">{e(preheader)}</div>
<table role="presentation" width="100%" cellspacing="0" cellpadding="0" style="background:#eeece5;"><tr><td align="center" style="padding:32px 16px;">
<table role="presentation" width="100%" cellspacing="0" cellpadding="0" style="max-width:600px;background:#faf7ef;border:1px solid #d9ded1;">
<tr><td style="padding:28px 32px 22px;border-bottom:1px solid #d9ded1;"><span style="font:600 17px Helvetica,Arial,sans-serif;letter-spacing:-.3px;">Hadithly</span><span style="float:right;font:11px Helvetica,Arial,sans-serif;letter-spacing:1.5px;color:#61746a;">A MOMENT TO READ</span></td></tr>
<tr><td style="padding:38px 32px 0;"><p style="font:11px Helvetica,Arial,sans-serif;letter-spacing:2px;color:#64786b;margin:0 0 22px;">READING, AT YOUR PACE</p><h1 style="font-size:42px;font-weight:400;line-height:1.09;letter-spacing:-1.2px;margin:0 0 28px;">{title}</h1><p style="font-size:18px;line-height:1.7;margin:0 0 32px;color:#42594e;">{e(intro)}</p></td></tr>
<tr><td style="padding:0 32px;"><table role="presentation" width="100%" cellspacing="0" cellpadding="0"><tr><td style="padding:24px;border-top:2px solid #325a47;border-bottom:1px solid #d9ded1;background:#f0f1e7;"><p style="font:600 12px Helvetica,Arial,sans-serif;letter-spacing:.5px;margin:0 0 12px;color:#325a47;">{e(tip)}</p><p style="font-size:16px;line-height:1.65;margin:0;color:#42594e;">{e(body)}</p></td></tr></table></td></tr>
<tr><td style="padding:30px 32px 42px;"><table role="presentation" cellspacing="0" cellpadding="0"><tr><td style="background:#244b3a;border-radius:4px;"><a href="{e(url)}" style="display:inline-block;padding:15px 22px;color:#ffffff;text-decoration:none;font:600 14px Helvetica,Arial,sans-serif;">{e(cta)} &nbsp; &#8594;</a></td></tr></table><p style="font-size:15px;line-height:1.6;color:#61746a;margin:22px 0 0;">{e(closing)}</p></td></tr>
<tr><td style="padding:24px 32px;border-top:1px solid #d9ded1;font:12px/1.7 Helvetica,Arial,sans-serif;color:#66746b;">{e(reason)}<br><a href="{{{{unsubscribe_url}}}}" style="color:#42594e;">Stop these emails</a> &nbsp; · &nbsp; <a href="https://hadithly.app/privacy/" style="color:#42594e;">Privacy</a><br>Hadithly · Quiet reading in your language.</td></tr>
</table></td></tr></table></body></html>'''
 (OUT/(slug+'.html')).write_text(letter)
 (OUT/(slug+'.txt')).write_text(f'{subject}\n\n{intro}\n\n{tip}\n{body}\n\n{cta}: {url}\n\n{closing}\n\n{reason}\nStop these emails: {{{{unsubscribe_url}}}}\nPrivacy: https://hadithly.app/privacy/\n')
 cards.append(f'<article><p class="timing">{e(timing)}</p><h2>{e(subject)}</h2><p class="preview">Preview: {e(preheader)}</p><iframe title="{e(subject)} draft" src="{slug}.html"></iframe><a href="{slug}.txt">Plain-text version</a></article>')
gallery='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Hadithly email drafts</title><style>*{box-sizing:border-box}body{margin:0;background:#142a22;color:#f4f0e5;font-family:Helvetica,Arial,sans-serif}main{max-width:1480px;padding:40px 24px 60px;margin:auto}.eyebrow,.timing{font-size:11px;letter-spacing:1.4px;text-transform:uppercase;color:#b7c9bb}h1{font:400 52px/1.1 Georgia,serif;letter-spacing:-1.5px;margin:16px 0}h2{font:400 23px Georgia,serif}.intro{max-width:700px;font-size:16px;line-height:1.7;color:#cad5cb}.grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:24px;margin-top:40px}.preview{font-size:13px;line-height:1.6;color:#b7c9bb;min-height:42px}iframe{width:100%;height:960px;border:0;background:#eeece5;margin:8px 0 16px}a{color:#cad5cb;font-size:13px}.draft{display:inline-block;border:1px solid #788e7b;padding:6px 10px;font-size:11px;letter-spacing:1px}@media(max-width:1050px){.grid{grid-template-columns:1fr}article{max-width:620px}h1{font-size:40px}}</style></head><body><main><span class="draft">UNSENT DRAFTS</span><p class="eyebrow">Hadithly · Optional reading tips</p><h1>A short series. Room to read.</h1><p class="intro">Three useful notes over twelve days, sent only after separate email consent. No reading-history triggers, open tracking, or pressure to return. The sequence ends after the third message.</p><div class="grid">'''+''.join(cards)+'''</div></main></body></html>'''
(OUT/'index.html').write_text(gallery)
print('Generated three HTML/text email drafts and preview gallery. No sending configuration.')
